<?php
session_start();require_once "config/conexao.php";
if($_SERVER["REQUEST_METHOD"]==="POST"){
$id=(int)($_POST["id"]??0);$tipo=$_POST["tipo"]??"";$ident=trim($_POST["identificacao"]??"");$rua=trim($_POST["rua"]??"");$numero=trim($_POST["numero"]??"");$cidade=trim($_POST["cidade"]??"");$estado=strtoupper(trim($_POST["estado"]??""));$cep=trim($_POST["cep"]??"");
if($ident!==""&&$rua!==""&&$cidade!==""&&in_array($tipo,["Origem","Destino","Ambos"])){
if($id){$st=$conn->prepare("UPDATE enderecos SET tipo=?,identificacao=?,rua=?,numero=?,cidade=?,estado=?,cep=? WHERE id=?");$st->bind_param("sssssssi",$tipo,$ident,$rua,$numero,$cidade,$estado,$cep,$id);}
else{$st=$conn->prepare("INSERT INTO enderecos(tipo,identificacao,rua,numero,cidade,estado,cep) VALUES(?,?,?,?,?,?,?)");$st->bind_param("sssssss",$tipo,$ident,$rua,$numero,$cidade,$estado,$cep);}
$st->execute();$_SESSION["mensagem"]="Endereço salvo com sucesso.";}else $_SESSION["mensagem"]="Preencha identificação, rua e cidade.";
header("Location: enderecos.php");exit;}
if(isset($_GET["excluir"])){$id=(int)$_GET["excluir"];$st=$conn->prepare("DELETE FROM enderecos WHERE id=?");$st->bind_param("i",$id);$st->execute();$_SESSION["mensagem"]="Endereço excluído, se não estiver vinculado a frete.";header("Location: enderecos.php");exit;}
$editar=null;if(isset($_GET["editar"])){$id=(int)$_GET["editar"];$st=$conn->prepare("SELECT * FROM enderecos WHERE id=?");$st->bind_param("i",$id);$st->execute();$editar=$st->get_result()->fetch_assoc();}
$lista=$conn->query("SELECT * FROM enderecos ORDER BY identificacao");$titulo="Endereços";include "includes/cabecalho.php";?>
<div class="container py-4"><h1 class="h3">Endereços</h1><p class="text-muted">Cadastre os locais de origem e destino.</p>
<div class="card border-0 shadow-sm mb-4"><div class="card-body"><h2 class="h5"><?= $editar?"Editar endereço":"Novo endereço" ?></h2><form method="post" class="row g-3"><input type="hidden" name="id" value="<?= (int)($editar["id"]??0) ?>">
<div class="col-md-3"><label class="form-label">Tipo</label><select name="tipo" class="form-select"><option <?= (($editar["tipo"]??"")=="Origem")?"selected":"" ?>>Origem</option><option <?= (($editar["tipo"]??"")=="Destino")?"selected":"" ?>>Destino</option><option <?= (($editar["tipo"]??"")=="Ambos")?"selected":"" ?>>Ambos</option></select></div>
<div class="col-md-9"><label class="form-label">Identificação *</label><input name="identificacao" class="form-control" required placeholder="Ex.: Depósito central" value="<?= htmlspecialchars($editar["identificacao"]??"") ?>"></div>
<div class="col-md-6"><label class="form-label">Rua *</label><input name="rua" class="form-control" required value="<?= htmlspecialchars($editar["rua"]??"") ?>"></div><div class="col-md-2"><label class="form-label">Número</label><input name="numero" class="form-control" value="<?= htmlspecialchars($editar["numero"]??"") ?>"></div><div class="col-md-2"><label class="form-label">Cidade *</label><input name="cidade" class="form-control" required value="<?= htmlspecialchars($editar["cidade"]??"") ?>"></div><div class="col-md-1"><label class="form-label">UF</label><input name="estado" maxlength="2" class="form-control" value="<?= htmlspecialchars($editar["estado"]??"") ?>"></div><div class="col-md-3"><label class="form-label">CEP</label><input name="cep" class="form-control" value="<?= htmlspecialchars($editar["cep"]??"") ?>"></div>
<div class="col-12"><button class="btn btn-primary">Salvar endereço</button><?php if($editar): ?> <a class="btn btn-outline-secondary" href="enderecos.php">Cancelar</a><?php endif; ?></div></form></div></div>
<div class="card border-0 shadow-sm"><div class="card-body"><h2 class="h5">Endereços cadastrados</h2><div class="table-responsive"><table class="table"><thead><tr><th>Identificação</th><th>Tipo</th><th>Local</th><th>Ações</th></tr></thead><tbody><?php while($e=$lista->fetch_assoc()): ?><tr><td><?= htmlspecialchars($e["identificacao"]) ?></td><td><?= htmlspecialchars($e["tipo"]) ?></td><td><?= htmlspecialchars($e["cidade"]."/".$e["estado"]) ?></td><td><a href="?editar=<?= $e["id"] ?>">Editar</a> · <a onclick="return confirm('Excluir este endereço?')" href="?excluir=<?= $e["id"] ?>">Excluir</a></td></tr><?php endwhile; ?></tbody></table></div></div></div></div><?php include "includes/rodape.php";?>